import { evaluateShortcutCondition } from "./src/hooks/utils/evaluateShortcutCondition";

const conditions = {
  canEdit: true,
  canCreate: false,
  readOnly: false,
  questionnairesEnabled: true,
  evil: "fetch('/x')",
};

const cases: [string, boolean][] = [
  ["always", true],
  ["canEdit", true],
  ["canCreate", false],
  ["!readOnly", true],
  ["canEdit && !readOnly", true],
  ["canEdit && readOnly", false],
  ["canEdit || canCreate", false || true],
  ["canCreate || readOnly", false],
  ["(canCreate || canEdit) && !readOnly", true],
  ["true", true],
  ["false", false],
  ["evil", true],
  ["fetch('/x')", false],
  ["unknownThing", false],
  ["canEdit &&", false],
  ["(canEdit", false],
  ["canEdit) ", false],
  ["window.alert(1)", false],
];

let failures = 0;
for (const [clause, expected] of cases) {
  const actual = evaluateShortcutCondition(clause, conditions);
  const status = actual === expected ? "OK  " : "FAIL";
  if (actual !== expected) failures += 1;
  console.log(`${status} ${JSON.stringify(clause)} -> ${actual} (expected ${expected})`);
}
console.log(failures === 0 ? "ALL PASS" : `${failures} FAILURES`);

